def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    total_d = sum(1 for x in op if x == 'D')
    if total_d == n:
        return 'D'

    w = 8 if n > 8 else n
    start = n - w
    opp_d = 0
    unprov = 0

    for i in range(start, n):
        if op[i] == 'D':
            opp_d += 1
        if my[i] == 'C' and op[i] == 'D' and (i == 0 or my[i - 1] == 'C'):
            unprov += 1

    if n >= 16 and total_d * 3 >= n * 2 and opp_d >= 3 and op[-4:].count('C') < 3:
        return 'D'

    run = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        run += 1
        i -= 1

    if run >= 4:
        return 'D'

    last_m = my[-1]
    last_o = op[-1]

    if last_o == 'D':
        if last_m == 'D':
            if unprov <= 1 and opp_d <= 2 and total_d * 2 <= n:
                return 'C'
            if unprov <= 2 and opp_d <= 3 and (n < 12 or total_d * 3 <= n * 2):
                return 'C'
            return 'D'

        if unprov >= 2 or opp_d >= 3 or run >= 2:
            return 'D'
        return 'C'

    if unprov >= 3 or opp_d >= 4 or (unprov >= 2 and opp_d >= 2 and total_d > n // 2):
        return 'D'

    return 'C'
